<template>
  <div class="mx-auto max-w-7xl space-y-6 pb-10">
    <Button label="Back to suppliers" icon="pi pi-arrow-left" severity="secondary" text @click="router.back()"/>
    <div v-if="loading" class="space-y-4"><Skeleton height="12rem" border-radius="1.5rem"/><Skeleton height="24rem" border-radius="1.5rem"/></div>
    <template v-else-if="supplier">
      <section class="relative overflow-hidden rounded-3xl bg-slate-950 px-7 py-8 text-white shadow-xl"><div class="absolute -right-20 -top-24 h-64 w-64 rounded-full bg-orange-400/20 blur-3xl"></div><div class="relative flex flex-col gap-6 md:flex-row md:items-center md:justify-between"><div class="flex items-center gap-5"><span class="flex h-16 w-16 items-center justify-center rounded-2xl bg-orange-300 text-xl font-bold text-slate-950">{{ initials(name) }}</span><div><p class="text-xs font-bold uppercase tracking-[.2em] text-orange-300">{{ supplier.supplier_code || `SUP-${supplier.id}` }}</p><h1 class="mt-2 text-3xl font-bold">{{ name }}</h1><p class="mt-2 text-sm text-slate-300">Supplier verification and credentials</p></div></div><div class="flex flex-wrap gap-2"><Tag :value="label(status)" :severity="severity(status)" rounded/><Button v-if="status==='pending'" label="Reject" severity="danger" outlined @click="rejectVisible=true"/><Button v-if="status==='pending'" label="Approve supplier" severity="success" :loading="acting" @click="approve"/></div></div></section>
      <section class="grid gap-6 lg:grid-cols-[1.15fr_.85fr]"><div class="space-y-6"><div class="rounded-3xl border border-slate-200 bg-white p-6 shadow-sm"><p class="text-xs font-bold uppercase tracking-[.18em] text-slate-400">Business profile</p><h2 class="mt-2 text-xl font-bold text-slate-900">Supplier information</h2><dl class="mt-6 grid gap-6 sm:grid-cols-2"><Info label="Company name" :value="name"/><Info label="Contact person" :value="supplier.contact_person"/><Info label="Email address" :value="supplier.email || portal?.user?.email"/><Info label="Phone number" :value="supplier.phone || supplier.mobile || portal?.phone"/><Info label="Business address" :value="supplier.address"/><Info label="Registered" :value="dateTime(supplier.created_at)"/></dl></div><div class="rounded-3xl border border-slate-200 bg-white p-6 shadow-sm"><div class="flex items-end justify-between"><div><p class="text-xs font-bold uppercase tracking-[.18em] text-slate-400">Attachments</p><h2 class="mt-2 text-xl font-bold text-slate-900">Verification documents</h2></div><span class="text-sm text-slate-500">{{ documents.length }} files</span></div><div v-if="documents.length" class="mt-6 grid gap-4 sm:grid-cols-2"><button v-for="doc in documents" :key="doc.id" class="group overflow-hidden rounded-2xl border border-slate-200 text-left transition hover:border-orange-300 hover:shadow-md" @click="preview(doc)"><div class="flex h-32 items-center justify-center bg-slate-100"><i :class="isImage(doc)?'pi pi-image':'pi pi-file-pdf'" class="text-3xl text-slate-400"></i></div><div class="p-4"><p class="truncate font-semibold text-slate-800">{{ doc.original_filename || doc.document_type }}</p><p class="mt-1 text-xs uppercase tracking-wider text-slate-500">{{ label(doc.document_type || 'document') }}</p></div></button></div><p v-else class="mt-6 rounded-2xl bg-slate-50 p-8 text-center text-sm text-slate-500">No documents were submitted.</p></div></div>
        <aside class="space-y-6"><div class="rounded-3xl border border-slate-200 bg-white p-6 shadow-sm"><p class="text-xs font-bold uppercase tracking-[.18em] text-slate-400">Review summary</p><div class="mt-5 space-y-4"><Signal icon="pi-file" label="Documents" :value="`${documents.length} submitted`" :good="documents.length>0"/><Signal icon="pi-verified" label="Decision" :value="label(status)" :good="status==='approved'"/></div></div><div v-if="portal?.verified_at || portal?.rejection_reason" class="rounded-3xl border border-slate-200 bg-white p-6 shadow-sm"><p class="text-xs font-bold uppercase tracking-[.18em] text-slate-400">Review outcome</p><dl class="mt-5 space-y-4"><Info label="Reviewed on" :value="dateTime(portal?.verified_at)"/><Info v-if="portal?.rejection_reason" label="Rejection reason" :value="portal.rejection_reason"/></dl></div></aside>
      </section>
    </template>
    <Dialog v-model:visible="previewVisible" modal maximizable header="Document preview" :style="{width:'min(920px, 95vw)'}"><div class="flex min-h-96 items-center justify-center bg-slate-100"><img v-if="previewUrl && isImage(selected)" :src="previewUrl" class="max-h-[70vh] max-w-full object-contain"/><iframe v-else-if="previewUrl" :src="previewUrl" class="h-[70vh] w-full"></iframe><ProgressSpinner v-else/></div></Dialog>
    <Dialog v-model:visible="rejectVisible" modal header="Reject supplier" :style="{width:'min(520px, 95vw)'}"><p class="mb-3 text-sm text-slate-600">Explain what the supplier needs to correct.</p><Textarea v-model="reason" rows="5" class="w-full" placeholder="Rejection reason (at least 10 characters)"/><template #footer><Button label="Cancel" severity="secondary" text @click="rejectVisible=false"/><Button label="Reject application" severity="danger" :disabled="reason.trim().length<10" :loading="acting" @click="reject"/></template></Dialog>
  </div>
</template>
<script setup lang="ts">
import { defineComponent,h,onBeforeUnmount,onMounted,ref } from 'vue';import { useRoute,useRouter } from 'vue-router';import Button from 'primevue/button';import Dialog from 'primevue/dialog';import ProgressSpinner from 'primevue/progressspinner';import Skeleton from 'primevue/skeleton';import Tag from 'primevue/tag';import Textarea from 'primevue/textarea';import { useToast } from 'primevue/usetoast';import axiosClient from '@/axios'
const Info=defineComponent({props:{label:String,value:[String,Number]},setup:p=>()=>h('div',[h('dt',{class:'text-xs font-semibold uppercase tracking-wider text-slate-400'},p.label),h('dd',{class:'mt-2 break-words font-medium text-slate-800'},p.value||'Not provided')])});const Signal=defineComponent({props:{icon:String,label:String,value:String,good:Boolean},setup:p=>()=>h('div',{class:'flex gap-3'},[h('span',{class:`flex h-10 w-10 items-center justify-center rounded-xl ${p.good?'bg-emerald-100 text-emerald-700':'bg-amber-100 text-amber-700'}`},[h('i',{class:`pi ${p.icon}`})]),h('div',[h('p',{class:'font-semibold text-slate-800'},p.label),h('p',{class:'mt-1 text-sm text-slate-500'},p.value)])])});const route=useRoute(),router=useRouter(),toast=useToast(),supplier=ref<any>(null),portal=ref<any>(null),documents=ref<any[]>([]),status=ref('pending'),loading=ref(true),acting=ref(false),rejectVisible=ref(false),reason=ref(''),previewVisible=ref(false),previewUrl=ref(''),selected=ref<any>(null);let objectUrl='';const name=ref('Unknown supplier');const load=async()=>{try{const response=await axiosClient.get(`/api/supplier-verifications/${route.params.id}`);portal.value=response.data?.data||response.data;const linkedSupplier=portal.value?.supplier||{};supplier.value={...linkedSupplier,supplier_name:portal.value?.supplier_name||portal.value?.company_name||linkedSupplier.supplier_name,contact_person:portal.value?.contact_person||linkedSupplier.contact_person,email:portal.value?.user?.email||linkedSupplier.email,phone:portal.value?.phone||linkedSupplier.phone,address:portal.value?.address||linkedSupplier.address,city:portal.value?.city||linkedSupplier.city,province:portal.value?.province||linkedSupplier.province};name.value=supplier.value.supplier_name||supplier.value.company_name||'Unknown supplier';status.value=String(portal.value?.status||'pending').toLowerCase();documents.value=portal.value?.verification_documents||portal.value?.verificationDocuments||[]}catch(error:any){toast.add({severity:'error',summary:'Unable to load supplier application',detail:error?.response?.data?.message||'Please try again.',life:3500})}finally{loading.value=false}};const portalId=()=>portal.value?.id||Number(route.params.id)||null;const approve=async()=>{if(!portalId())return;acting.value=true;try{await axiosClient.post(`/api/supplier-verifications/${portalId()}/approve`);status.value='approved';toast.add({severity:'success',summary:'Supplier approved',life:2500})}finally{acting.value=false}};const reject=async()=>{acting.value=true;try{await axiosClient.post(`/api/supplier-verifications/${portalId()}/reject`,{rejection_reason:reason.value});status.value='rejected';rejectVisible.value=false;toast.add({severity:'success',summary:'Supplier rejected',life:2500})}finally{acting.value=false}};const preview=async(doc:any)=>{selected.value=doc;previewVisible.value=true;const r=await axiosClient.get(`/api/supplier-verifications/documents/${doc.id}/download`,{responseType:'blob'});objectUrl=URL.createObjectURL(new Blob([r.data],{type:r.headers['content-type']}));previewUrl.value=objectUrl};const isImage=(d:any)=>/image\//.test(d?.file_mime_type||d?.mime_type||'')||/\.(png|jpe?g|gif|webp)$/i.test(d?.original_filename||'');const label=(v:string)=>String(v||'').replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase());const severity=(v:string)=>v==='approved'?'success':v==='rejected'?'danger':'warn';const initials=(v:string)=>v.split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase();const dateTime=(v:any)=>v?new Intl.DateTimeFormat('en-PH',{dateStyle:'medium',timeStyle:'short'}).format(new Date(v)):'Not provided';onMounted(load);onBeforeUnmount(()=>{if(objectUrl)URL.revokeObjectURL(objectUrl)})
</script>
